/* === Volta Studio CSS === */
/* Design: Minimal, editorial, warm */
/* OKLCH Color Palette */

:root {
  --bg-primary: oklch(96% 0.008 85);
  --bg-secondary: oklch(94% 0.006 85);
  --text-primary: oklch(14% 0.01 85);
  --text-secondary: oklch(40% 0.01 85);
  --text-muted: oklch(55% 0.008 85);
  --accent-warm: oklch(58% 0.13 52);
  --accent-sage: oklch(72% 0.04 145);
  --accent-sand: oklch(78% 0.06 78);
  --accent-terracotta: oklch(55% 0.14 40);
  --accent-rose: oklch(65% 0.08 15);
  --border-subtle: oklch(88% 0.006 85);
  --marquee-bg: oklch(93% 0.005 85);

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --space-9: 120px;
  --space-10: 160px;
}

/* === Reset === */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

/* === Typography === */
h1, h2, h3, h4, .serif {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-weight: 400;
  line-height: 1.15;
}

.body-text {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.body-text p + p {
  margin-top: var(--space-4);
}

/* === Header / Navigation === */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: var(--space-5) var(--space-6);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: transparent;
  transition: background 0.3s ease;
}

.site-header.scrolled {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-subtle);
}

.logo {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.logo span {
  color: var(--text-muted);
  font-weight: 400;
  font-size: 0.75rem;
  vertical-align: super;
  margin-left: 1px;
}

.nav-desktop {
  display: flex;
  gap: var(--space-5);
  align-items: center;
}

.nav-desktop a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color 0.2s ease;
}

.nav-desktop a:hover,
.nav-desktop a.active {
  color: var(--text-primary);
}

/* === Hamburger === */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 200;
  position: relative;
  padding: 0;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text-primary);
  transition: all 0.3s ease;
  position: absolute;
}

.hamburger span:nth-child(1) {
  transform: translateY(-6px);
}

.hamburger span:nth-child(2) {
  transform: translateY(6px);
}

.hamburger.open span:nth-child(1) {
  transform: rotate(45deg);
}

.hamburger.open span:nth-child(2) {
  transform: rotate(-45deg);
}

/* === Mobile Menu Overlay === */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg-primary);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-menu.open {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu nav {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-6);
}

.mobile-menu a {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: 2.5rem;
  font-weight: 400;
  color: var(--text-primary);
  transition: opacity 0.2s ease;
}

.mobile-menu a:hover {
  opacity: 0.6;
}

/* === Section Padding === */
.section {
  padding: var(--space-9) var(--space-6);
}

@media (min-width: 1024px) {
  .section {
    padding: var(--space-10) var(--space-8);
  }
}

/* === Hero === */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 120px;
  padding-bottom: var(--space-8);
}

.hero h1 {
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 400;
  line-height: 1.1;
  max-width: 14ch;
  letter-spacing: -0.02em;
}

@media (min-width: 768px) {
  .hero h1 {
    max-width: 12ch;
  }
}

/* === Media Showcase === */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-3);
  width: 100%;
}

@media (min-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr 1fr 1fr;
    gap: var(--space-4);
  }
}

.media-block {
  aspect-ratio: 4/3;
  border-radius: 2px;
}

.media-block:nth-child(1) { background: var(--accent-terracotta); }
.media-block:nth-child(2) { background: var(--accent-sage); }
.media-block:nth-child(3) { background: var(--accent-sand); }

/* === Client Marquee === */
.marquee-section {
  padding: var(--space-8) 0;
  overflow: hidden;
  background: var(--marquee-bg);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.marquee-track {
  display: flex;
  gap: var(--space-6);
  white-space: nowrap;
  width: max-content;
}

.marquee-row {
  padding: var(--space-4) 0;
  overflow: hidden;
}

.marquee-row:nth-child(odd) .marquee-track {
  animation: scroll-left 35s linear infinite;
}

.marquee-row:nth-child(even) .marquee-track {
  animation: scroll-right 35s linear infinite;
}

.marquee-row:nth-child(3) .marquee-track {
  animation: scroll-left 40s linear infinite;
}

.marquee-name {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 400;
  color: var(--text-primary);
  opacity: 0.85;
  padding: 0 var(--space-4);
}

.marquee-name::after {
  content: "◦";
  margin-left: var(--space-6);
  color: var(--text-muted);
  font-size: 0.5em;
  vertical-align: middle;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-track:hover {
  animation-play-state: paused;
}

/* === About Section === */
.about-section h2 {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: var(--space-5);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.about-content {
  max-width: 680px;
}

.about-content p {
  font-size: clamp(1.125rem, 2vw, 1.375rem);
  line-height: 1.75;
  color: var(--text-secondary);
  margin-bottom: var(--space-4);
}

/* === Page Header (non-home) === */
.page-header {
  padding-top: 160px;
  padding-bottom: var(--space-7);
}

.page-header h1 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 400;
  letter-spacing: -0.02em;
}

/* === Founder Letter (neweno.html) === */
.founder-letter {
  max-width: 640px;
  margin: 0 auto;
  padding-top: var(--space-6);
  padding-bottom: var(--space-10);
}

.founder-letter h1 {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 400;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-6);
}

.founder-letter .signature {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: 1.5rem;
  margin-top: var(--space-7);
  color: var(--text-primary);
}

.founder-letter p {
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--text-secondary);
  margin-bottom: var(--space-4);
}

.founder-letter .dropcap::first-letter {
  float: left;
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: 4.5rem;
  line-height: 0.8;
  padding-right: 12px;
  padding-top: 4px;
  color: var(--accent-warm);
}

/* === Philosophy (services.html) === */
.philosophy-section {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.philosophy-section h2 {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 400;
  margin-bottom: var(--space-5);
}

.philosophy-section .philosophy-text {
  max-width: 640px;
}

.philosophy-section p {
  font-size: 1.125rem;
  line-height: 1.75;
  color: var(--text-secondary);
  margin-bottom: var(--space-4);
}

/* === Divider === */
.divider {
  height: 1px;
  background: var(--border-subtle);
  width: 100%;
}

/* === Service Details (services.html) === */
.service-details-section h2 {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 400;
  margin-bottom: var(--space-7);
}

.service-card {
  max-width: 640px;
  margin-bottom: var(--space-7);
}

.service-card h3 {
  font-size: 1.375rem;
  font-weight: 600;
  margin-bottom: var(--space-3);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.service-card p {
  font-size: 1.125rem;
  line-height: 1.75;
  color: var(--text-secondary);
}

/* === Clients Grid (clients.html) === */
.clients-heading h2 {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 400;
  margin-bottom: var(--space-2);
}

.clients-heading .clients-subtitle {
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: var(--space-7);
}

.clients-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

@media (min-width: 768px) {
  .clients-grid {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-7) var(--space-6);
  }
}

@media (min-width: 1024px) {
  .clients-grid {
    grid-template-columns: 1fr 1fr 1fr;
    gap: var(--space-7) var(--space-8);
  }
}

.client-item h3 {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: var(--space-2);
  color: var(--text-primary);
}

.client-item p {
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--text-secondary);
}

/* === Contact (contact.html) === */
.contact-hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding-top: 120px;
  padding-bottom: var(--space-8);
}

.contact-hero h1 {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-8);
  color: var(--text-primary);
}

.contact-links {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-5);
}

.contact-links a {
  font-size: 1.25rem;
  color: var(--text-secondary);
  transition: color 0.2s ease;
  letter-spacing: 0.02em;
}

.contact-links a:hover {
  color: var(--text-primary);
}

/* === Utilities === */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-5);
}

@media (min-width: 768px) {
  .container {
    padding: 0 var(--space-6);
  }
}

/* === Footer === */
.site-footer {
  padding: var(--space-7) var(--space-6);
  text-align: center;
  border-top: 1px solid var(--border-subtle);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* === Responsive: Mobile Navigation === */
@media (max-width: 767px) {
  .nav-desktop {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .site-header {
    padding: var(--space-4) var(--space-4);
  }

  .section {
    padding: var(--space-7) var(--space-4);
  }

  .page-header {
    padding-top: 120px;
  }
}

/* === Reduced motion === */
@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation: none !important;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

