/* === Volta Studio CSS === */
/* Design: Minimal, editorial, warm */
/* OKLCH Color Palette */

:root {
  --bg-primary: oklch(96% 0.008 85);
  --bg-secondary: oklch(94% 0.006 85);
  --text-primary: oklch(14% 0.01 85);
  --text-secondary: oklch(40% 0.01 85);
  --text-muted: oklch(55% 0.008 85);
  --accent-warm: oklch(58% 0.13 52);
  --accent-sage: oklch(72% 0.04 145);
  --accent-sand: oklch(78% 0.06 78);
  --accent-terracotta: oklch(55% 0.14 40);
  --accent-rose: oklch(65% 0.08 15);
  --border-subtle: oklch(88% 0.006 85);
  --marquee-bg: oklch(93% 0.005 85);

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --space-9: 120px;
  --space-10: 160px;
}

/* === Reset === */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

/* === Typography === */
h1, h2, h3, h4, .serif {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
  font-weight: 400;
  line-height: 1.15;
}

.body-text {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.body-text p + p {
  margin-top: var(--space-4);
}

/* === Header / Navigation === */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
